import { useAuthStore } from "../store/useAuthStore";
import type { PushToJiraResponse } from "../types/prd.types";

const API_BASE_URL = "/api/v1/scrum/backlog/generated";

const handleAuthError = (res: Response) => {
  if (res.status === 401) {
    console.warn("Received 401 - Logging out");
    useAuthStore.getState().logout();
    throw new Error("Session expired. Please login again.");
  }
};

export interface GeneratedBacklog {
  _id: string;
  userId: string;
  sessionId: string;
  projectKey: string;
  status: 'pending_review' | 'partially_pushed' | 'fully_pushed' | 'rejected';
  orchestrator_contract: any;
  stories: any[];
  epic_statuses: any[];
  validation_report: any;
  createdAt: string;
  updatedAt: string;
}

export const getGeneratedBacklog = async (id: string): Promise<GeneratedBacklog> => {
  const response = await fetch(`${API_BASE_URL}/${id}`, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${localStorage.getItem("token")}`,
    },
  });

  handleAuthError(response);

  if (!response.ok) {
    throw new Error("Failed to fetch generated backlog");
  }

  return response.json();
};

export const updateStory = async (backlogId: string, storyId: string, updates: any): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${backlogId}/stories/${storyId}`, {
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${localStorage.getItem("token")}`,
    },
    body: JSON.stringify(updates),
  });

  handleAuthError(response);

  if (!response.ok) {
    throw new Error("Failed to update story");
  }
};

export const approveAndPushEpic = async (backlogId: string, epicId: string | null): Promise<void> => {
  const response = await fetch(`${API_BASE_URL}/${backlogId}/approve`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${localStorage.getItem("token")}`,
    },
    body: JSON.stringify({ epicId }),
  });

  handleAuthError(response);

  if (!response.ok) {
    throw new Error("Failed to approve and push");
  }
};

import React, { useEffect, useState } from "react";
import type { PushedBacklogRecord } from "../../types/chat.types";
import { getPushHistory } from "../../api/backlogApi";

interface PushHistoryPanelProps {
  sessionId?: string | null;
  refreshTrigger?: number; // increment to trigger refresh
}

const TYPE_COLORS: Record<string, string> = {
  Epic: "bg-[var(--color-purple-subtle)] text-[var(--color-purple)]",
  Story: "bg-[var(--color-success-subtle)] text-[var(--color-success)]",
  Task: "bg-[var(--color-info-subtle)] text-[var(--color-info)]",
  Subtask: "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)]",
  Bug: "bg-[var(--color-error-light)] text-[var(--color-error)]",
};

const PushHistoryPanel: React.FC<PushHistoryPanelProps> = ({
  sessionId,
  refreshTrigger,
}) => {
  const [history, setHistory] = useState<PushedBacklogRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [filter, setFilter] = useState<"all" | "session">("all");

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const data = await getPushHistory(
        filter === "session" ? sessionId || undefined : undefined
      );
      setHistory(data);
    } catch (err) {
      console.error("Failed to load push history:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen) {
      fetchHistory();
    }
  }, [isOpen, filter, refreshTrigger]);

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return "Just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <>
      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`push-history-toggle hover-lift hover-glow shadow-[var(--shadow-elevation-md)] ${isOpen ? "open" : ""}`}
      >
        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
          />
        </svg>
        <span className="push-history-toggle-text">
          Push History
          {history.length > 0 && !isOpen && (
            <span className="push-history-badge shadow-sm">
              {history.length}
            </span>
          )}
        </span>
      </button>

      {/* Backdrop */}
      {isOpen && (
        <div
          className="modal-overlay"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* Slide-over Panel */}
      <div className={`slide-over-panel ${isOpen ? "open" : ""}`}>
        {/* Panel Header */}
        <div className="slide-over-header">
          <div>
            <h2 className="heading-md m-0">Push History</h2>
            <p className="text-xs text-[var(--color-text-tertiary)] font-medium mt-1 uppercase tracking-wider">
              Items pushed to Jira
            </p>
          </div>
          <button
            onClick={() => setIsOpen(false)}
            className="btn-icon text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-secondary)]"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        {/* Filter Tabs */}
        {sessionId && (
          <div className="flex px-6 pt-4 gap-2">
            <button
              onClick={() => setFilter("all")}
              className={`px-4 py-1.5 text-xs rounded-full transition-all font-semibold ${
                filter === "all"
                  ? "bg-[var(--color-accent)] text-white shadow-sm"
                  : "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)]"
              }`}
            >
              All Sessions
            </button>
            <button
              onClick={() => setFilter("session")}
              className={`px-4 py-1.5 text-xs rounded-full transition-all font-semibold ${
                filter === "session"
                  ? "bg-[var(--color-accent)] text-white shadow-sm"
                  : "bg-[var(--color-bg-secondary)] text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)]"
              }`}
            >
              This Session
            </button>
          </div>
        )}

        {/* History List */}
        <div className="slide-over-body custom-scrollbar">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="flex gap-1">
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "0ms" }}></div>
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "150ms" }}></div>
                  <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-full animate-bounce" style={{ animationDelay: "300ms" }}></div>
              </div>
            </div>
          ) : history.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state-icon border border-[var(--color-border-light)]">
                  <svg
                    className="w-8 h-8 text-[var(--color-text-tertiary)]"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={1.5}
                      d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                    />
                  </svg>
              </div>
              <p className="empty-state-title">No items pushed yet</p>
              <p className="empty-state-desc">
                Craft backlog items in the chat and push them to Jira
              </p>
            </div>
          ) : (
            history.map((item, index) => (
              <div
                key={item._id}
                className="history-card animate-fade-in-up"
                style={{ animationDelay: `${index * 0.05}s` }}
              >
                <div className="history-card-header">
                  <div className="history-card-content">
                    <div className="history-card-tags">
                      <span
                        className={`history-card-type ${
                          TYPE_COLORS[item.type] || TYPE_COLORS.Task
                        }`}
                      >
                        {item.type}
                      </span>
                      {item.jiraUrl ? (
                        <a
                          href={item.jiraUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="history-card-key"
                        >
                          {item.jiraKey}
                        </a>
                      ) : (
                        <span className="history-card-key">
                          {item.jiraKey}
                        </span>
                      )}
                    </div>
                    <p className="history-card-summary">
                      {item.summary}
                    </p>
                    {item.parentKey && (
                      <div className="history-card-parent">
                        <svg fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 11l5-5m0 0l5 5m-5-5v12" /></svg>
                        <span className="history-card-parent-text">Under {item.parentKey}</span>
                        {item.parentSummary && (
                          <span className="history-card-parent-summary">— {item.parentSummary}</span>
                        )}
                      </div>
                    )}
                  </div>
                  <div className="history-card-meta">
                    <p className="history-card-date">
                      {formatDate(item.createdAt)}
                    </p>
                    {item.storyPoints && (
                      <p className="history-card-points">
                        {item.storyPoints} SP
                      </p>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </>
  );
};

export default PushHistoryPanel;

import React, { useState, useEffect } from 'react';
import { ChevronRight, ChevronDown, CheckSquare, Square } from 'lucide-react';
import type { EpicSuggestion, StorySuggestion, TaskSuggestion } from '../../types/prd.types';
import { StoryItem } from './StoryItem';
import { usePRDSelection } from '../../hooks/usePRDSelection';

interface EpicSectionProps {
    epic: EpicSuggestion;
    epicIndex: number;
    isSelected: boolean;
    isExpanded: boolean;
    selectionInfo: ReturnType<typeof usePRDSelection>;
    onToggle: () => void;
    onToggleStory: (storyIndex: number) => void;
    onToggleTask: (storyIndex: number, taskIndex: number) => void;
    onExpand: () => void;
    onExpandStory: (id: string) => void;
    onUpdate: (updates: Partial<EpicSuggestion>) => void;
    onUpdateStory: (storyIndex: number, updates: Partial<StorySuggestion>) => void;
    onUpdateTask: (storyIndex: number, taskIndex: number, updates: Partial<TaskSuggestion>) => void;
    onOpenModal?: (type: 'Epic' | 'Story' | 'Task', epicIndex: number, storyIndex?: number, taskIndex?: number) => void;
}

export const EpicSection: React.FC<EpicSectionProps> = ({
    epic,
    epicIndex,
    isSelected,
    isExpanded,
    selectionInfo,
    onToggle,
    onToggleStory,
    onToggleTask,
    onExpand,
    onExpandStory,
    onUpdate,
    onUpdateStory,
    onUpdateTask,
    onOpenModal
}) => {
    const hasStories = epic.issues && epic.issues.length > 0;

    // Calculate intermediate state
    const selectedStoryCount = Object.values(selectionInfo.selection[epicIndex]?.stories || {}).filter(s => s.selected).length;
    const isIndeterminate = !isSelected && selectedStoryCount > 0 && selectedStoryCount < epic.issues.length;

    return (
        <div className="card mb-4 overflow-hidden">
            {/* Header / Epic Card */}
            <div className={`
                p-4 flex items-start gap-3 
                ${isExpanded ? 'bg-[var(--color-bg-secondary)] border-b border-[var(--color-border-light)]' : 'bg-[var(--color-surface)]'}
                transition-colors
            `}>
                <button
                    onClick={onExpand}
                    className="mt-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-text-primary)] transition-colors"
                >
                    {isExpanded ? <ChevronDown className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
                </button>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                        <span className="badge badge-accent uppercase tracking-wider">
                            Epic
                        </span>
                        <div className="flex-1 min-w-0">
                            <h3
                                onClick={() => onOpenModal && onOpenModal('Epic', epicIndex)}
                                className="text-base font-semibold text-[var(--color-text-primary)] truncate cursor-pointer hover:text-[var(--color-accent)] transition-colors min-h-[24px] flex items-center gap-2 group/title"
                                title="Click to view/edit details"
                            >
                                {epic.title || <span className="text-[var(--color-text-tertiary)] italic font-normal">Empty epic title</span>}
                            </h3>
                        </div>
                    </div>
                    <p className="text-sm text-[var(--color-text-secondary)] line-clamp-2 pl-1">
                        {epic.description}
                    </p>
                </div>

                <button
                    onClick={onToggle}
                    className="mt-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] transition-colors relative"
                >
                    {isSelected ? (
                        <CheckSquare className="w-5 h-5 text-[var(--color-accent)]" />
                    ) : isIndeterminate ? (
                        <div className="relative w-5 h-5">
                            <Square className="w-5 h-5" />
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-2.5 h-2.5 bg-[var(--color-accent)] rounded-sm"></div>
                            </div>
                        </div>
                    ) : (
                        <Square className="w-5 h-5" />
                    )}
                </button>
            </div>

            {/* Stories List */}
            {isExpanded && hasStories && (
                <div className="p-2 space-y-1 bg-[var(--color-surface)]">
                    {epic.issues.map((story, storyIndex) => (
                        <StoryItem
                            key={storyIndex}
                            story={story}
                            isSelected={!!selectionInfo.selection[epicIndex]?.stories?.[storyIndex]?.selected}
                            selectionState={selectionInfo.selection[epicIndex]?.stories?.[storyIndex] || { selected: false, tasks: {} }}
                            isExpanded={!!selectionInfo.expanded[`story-${epicIndex}-${storyIndex}`]}
                            onToggle={() => onToggleStory(storyIndex)}
                            onToggleTask={(taskIndex) => onToggleTask(storyIndex, taskIndex)}
                            onExpand={() => onExpandStory(`story-${epicIndex}-${storyIndex}`)}
                            onUpdate={(updates) => onUpdateStory(storyIndex, updates)}
                            onUpdateTask={(taskIndex, updates) => onUpdateTask(storyIndex, taskIndex, updates)}
                            onOpenModal={(type, _, storyIdx, taskIdx) => onOpenModal && onOpenModal(type, epicIndex, storyIdx !== undefined ? storyIdx : storyIndex, taskIdx)}
                            isLast={storyIndex === epic.issues.length - 1}
                        />
                    ))}
                </div>
            )}

            {isExpanded && !hasStories && (
                <div className="p-8 text-center text-[var(--color-text-tertiary)] text-sm">
                    No user stories generated for this epic.
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { CheckSquare, Square, ChevronRight, ChevronDown } from 'lucide-react';
import type { StorySuggestion, TaskSuggestion } from '../../types/prd.types';
import { TaskItem } from './TaskItem';

interface StoryItemProps {
    story: StorySuggestion;
    isSelected: boolean;
    isExpanded: boolean;
    selectionState: { selected: boolean; tasks: Record<number, boolean> };
    onToggle: () => void;
    onToggleTask: (taskIndex: number) => void;
    onExpand: () => void;
    onUpdate: (updates: Partial<StorySuggestion>) => void;
    onUpdateTask: (taskIndex: number, updates: Partial<TaskSuggestion>) => void;
    isLast: boolean;
    onOpenModal?: (type: 'Story' | 'Task', dummy1: number, dummy2?: number, taskIndex?: number) => void;
}

export const StoryItem: React.FC<StoryItemProps> = ({
    story,
    isSelected,
    isExpanded,
    selectionState,
    onToggle,
    onToggleTask,
    onExpand,
    onUpdate,
    onUpdateTask,
    isLast,
    onOpenModal
}) => {
    const hasTasks = story.sub_issues && story.sub_issues.length > 0;

    // Determine partial selection state
    const selectedTaskCount = Object.values(selectionState.tasks || {}).filter(Boolean).length;
    const isIndeterminate = !isSelected && selectedTaskCount > 0 && selectedTaskCount < (story.sub_issues?.length || 0);

    return (
        <div className="relative">
            {/* Tree connector line */}
            <div className={`absolute left-[11px] top-0 w-[1px] bg-[var(--color-border)] ${isLast && !isExpanded ? 'h-6' : 'h-full'}`}></div>

            <div className={`
                flex items-start group relative py-2 pl-2 pr-2 rounded-lg transition-all duration-200
                ${isSelected ? 'bg-[var(--color-accent-lighter)]' : 'hover:bg-[var(--color-bg-secondary)]'}
            `}>
                {/* Horizontal connector to parent */}
                <div className="absolute left-[-13px] top-5 w-4 h-[1px] bg-[var(--color-border)]"></div>

                <div className="flex items-center mt-0.5 mr-2">
                    <button
                        onClick={onExpand}
                        disabled={!hasTasks}
                        className={`p-0.5 rounded-md transition-colors ${hasTasks ? 'hover:bg-[var(--color-bg-tertiary)] text-[var(--color-text-secondary)]' : 'text-transparent'}`}
                    >
                        {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                    </button>

                    <button
                        onClick={onToggle}
                        className="ml-1 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] transition-colors focus:outline-none relative"
                    >
                        {isSelected ? (
                            <CheckSquare className="w-4 h-4 text-[var(--color-accent)]" />
                        ) : isIndeterminate ? (
                            <div className="relative w-4 h-4">
                                <Square className="w-4 h-4" />
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <div className="w-2 h-2 bg-[var(--color-accent)] rounded-sm"></div>
                                </div>
                            </div>
                        ) : (
                            <Square className="w-4 h-4" />
                        )}
                    </button>
                </div>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                        <span className="badge badge-accent uppercase tracking-wide">
                            Story
                        </span>
                        <div className="flex-1 min-w-0">
                            <h4
                                onClick={() => onOpenModal && onOpenModal('Story', 0)}
                                className="text-sm font-medium text-[var(--color-text-primary)] truncate cursor-pointer hover:text-[var(--color-accent)] transition-colors min-h-[20px]"
                                title="Click to view/edit details"
                            >
                                {story.summary || <span className="text-[var(--color-text-tertiary)] italic font-normal">Empty story summary</span>}
                            </h4>
                        </div>
                        <div className="flex items-center text-xs text-[var(--color-text-tertiary)] gap-3 shrink-0">
                            {story.story_points && (
                                <span className="badge badge-neutral whitespace-nowrap">
                                    {story.story_points} pts
                                </span>
                            )}
                            <span className="whitespace-nowrap">{story.priority || 'Medium'}</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Children Tasks */}
            {isExpanded && hasTasks && (
                <div className="ml-6 pl-2 border-l border-transparent"> {/* Offset for children */}
                    {story.sub_issues.map((task, index) => {
                        const isTaskSelected = selectionState?.tasks?.[index];
                        return (
                            <TaskItem
                                key={index}
                                task={task}
                                isSelected={isTaskSelected !== undefined ? isTaskSelected : isSelected}
                                onToggle={() => onToggleTask(index)}
                                onUpdate={(updates) => onUpdateTask(index, updates)}
                                onOpenModal={() => onOpenModal && onOpenModal('Task', 0, 0, index)}
                                isLast={index === (story.sub_issues?.length || 0) - 1}
                            />
                        );
                    })}
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { CheckSquare, Square } from 'lucide-react';
import type { TaskSuggestion } from '../../types/prd.types';

interface TaskItemProps {
    task: TaskSuggestion;
    isSelected: boolean;
    onToggle: () => void;
    onUpdate: (updates: Partial<TaskSuggestion>) => void;
    isLast: boolean;
    onOpenModal?: () => void;
}

export const TaskItem: React.FC<TaskItemProps> = ({ task, isSelected, onToggle, onUpdate, isLast, onOpenModal }) => {


    return (
        <div className="flex items-start group relative pl-6 py-2 hover:bg-[var(--color-bg-secondary)] rounded-md transition-colors">
            {/* Tree connector line */}
            <div className={`absolute left-[11px] top-0 w-[1px] bg-[var(--color-border)] ${isLast ? 'h-5' : 'h-full'}`}></div>
            <div className="absolute left-[11px] top-5 w-3 h-[1px] bg-[var(--color-border)]"></div>

            <button
                onClick={onToggle}
                className="mt-0.5 mr-3 shrink-0 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] transition-colors focus:outline-none"
            >
                {isSelected ? (
                    <CheckSquare className="w-4 h-4 text-[var(--color-accent)]" />
                ) : (
                    <Square className="w-4 h-4" />
                )}
            </button>

            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                    <span className="text-xs font-mono text-[var(--color-text-tertiary)] uppercase tracking-wider shrink-0">Task</span>
                    <span
                        onClick={() => onOpenModal && onOpenModal()}
                        className="text-sm text-[var(--color-text-secondary)] truncate cursor-pointer hover:text-[var(--color-accent)] flex-1 min-h-[20px] min-w-0"
                        title="Click to view/edit details"
                    >
                        {task.summary || <span className="text-[var(--color-text-tertiary)] italic">Empty task summary</span>}
                    </span>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { X, Save, Play, Loader2, ListTodo, AlignLeft } from 'lucide-react';
import type { EpicSuggestion, StorySuggestion, TaskSuggestion } from '../../types/prd.types';

export type TicketType = 'Epic' | 'Story' | 'Task';

export interface TicketDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    ticketType: TicketType | null;
    ticketData: EpicSuggestion | StorySuggestion | TaskSuggestion | null;
    onSave: (updates: Record<string, unknown>) => void;
    onPush?: () => void;
    isPushing?: boolean;
}

export const TicketDetailModal: React.FC<TicketDetailModalProps> = ({
    isOpen,
    onClose,
    ticketType,
    ticketData,
    onSave,
    onPush,
    isPushing = false
}) => {
    // Local state for editing
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [acceptanceCriteria, setAcceptanceCriteria] = useState('');
    const [storyPoints, setStoryPoints] = useState<number | ''>('');
    const [priority, setPriority] = useState('Medium');

    // eslint-disable-next-line
    useEffect(() => {
        if (ticketData) {
            setTitle((ticketData as EpicSuggestion).title || (ticketData as StorySuggestion).summary || '');
            setDescription(ticketData.description || '');
            if (ticketType === 'Story') {
                const story = ticketData as StorySuggestion;
                setAcceptanceCriteria(story.acceptance_criteria?.join('\n') || '');
                setStoryPoints(story.story_points ?? '');   
                setPriority(story.priority || 'Medium');
            } else if (ticketType === 'Task') {
                const task = ticketData as TaskSuggestion;
                setPriority(task.priority || 'Medium');
            }
        }
    }, [ticketData, ticketType, isOpen]);

    if (!isOpen || !ticketData || !ticketType) return null;

    const handleSave = () => {
        const updates: Record<string, unknown> = {};
        if (ticketType === 'Epic') {
            updates.title = title;
            updates.description = description;
        } else if (ticketType === 'Story') {
            updates.summary = title;
            updates.description = description;
            updates.acceptance_criteria = acceptanceCriteria.split('\n').map(s => s.trim()).filter(s => s.length > 0);
            updates.story_points = storyPoints === '' ? undefined : Number(storyPoints);
            updates.priority = priority;
        } else if (ticketType === 'Task') {
            updates.summary = title;
            updates.description = description;
            updates.priority = priority;
        }
        onSave(updates);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-[var(--color-bg-primary)] rounded-xl shadow-xl w-full max-w-3xl flex flex-col max-h-[90vh] overflow-hidden border border-[var(--color-border)]">
                {/* Header */}
                <div className="flex items-center justify-between p-5 border-b border-[var(--color-border)] bg-[var(--color-bg-secondary)]">
                    <div className="flex items-center gap-3">
                        <span className={`px-2 py-1 text-xs font-bold uppercase tracking-wider rounded ${
                            ticketType === 'Epic' ? 'bg-purple-100 text-purple-700' :
                            ticketType === 'Story' ? 'bg-blue-100 text-blue-700' :
                            'bg-green-100 text-green-700'
                        }`}>
                            {ticketType}
                        </span>
                        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Edit Details</h2>
                    </div>
                    <button onClick={onClose} className="p-2 text-[var(--color-text-tertiary)] hover:text-[var(--color-text-primary)] transition-colors rounded-md hover:bg-[var(--color-bg-tertiary)]">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                    {/* Title / Summary */}
                    <div>
                        <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                            {ticketType === 'Epic' ? 'Title' : 'Summary'}
                        </label>
                        <input
                            type="text"
                            value={title}
                            onChange={e => setTitle(e.target.value)}
                            className="input w-full text-base font-medium"
                            placeholder={`Enter ${ticketType.toLowerCase()} ${ticketType === 'Epic' ? 'title' : 'summary'}`}
                        />
                    </div>

                    {/* Description */}
                    <div>
                        <label className="flex items-center gap-2 text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                            <AlignLeft className="w-4 h-4" /> Description
                        </label>
                        <textarea
                            value={description}
                            onChange={e => setDescription(e.target.value)}
                            className="input w-full h-32 py-3 custom-scrollbar"
                            placeholder={`Enter detailed description for this ${ticketType.toLowerCase()}...`}
                        />
                    </div>

                    {/* Story Specific Fields */}
                    {ticketType === 'Story' && (
                        <>
                            <div>
                                <label className="flex items-center gap-2 text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                    <ListTodo className="w-4 h-4" /> Acceptance Criteria
                                </label>
                                <textarea
                                    value={acceptanceCriteria}
                                    onChange={e => setAcceptanceCriteria(e.target.value)}
                                    className="input w-full h-32 py-3 custom-scrollbar font-mono text-sm"
                                    placeholder="One criterion per line..."
                                />
                            </div>
                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                        Story Points
                                    </label>
                                    <input
                                        type="number"
                                        value={storyPoints}
                                        onChange={e => setStoryPoints(e.target.value === '' ? '' : Number(e.target.value))}
                                        className="input w-full"
                                        min="0"
                                        max="100"
                                    />
                                </div>
                                <div className="flex-1">
                                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                        Priority
                                    </label>
                                    <select
                                        value={priority}
                                        onChange={e => setPriority(e.target.value)}
                                        className="input w-full bg-white"
                                    >
                                        <option value="Highest">Highest</option>
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                        <option value="Lowest">Lowest</option>
                                    </select>
                                </div>
                            </div>
                        </>
                    )}

                    {/* Task Specific Fields */}
                    {ticketType === 'Task' && (
                        <div className="flex-1">
                            <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-2">
                                Priority
                            </label>
                            <select
                                value={priority}
                                onChange={e => setPriority(e.target.value)}
                                className="input w-full bg-white"
                            >
                                <option value="Highest">Highest</option>
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                                <option value="Lowest">Lowest</option>
                            </select>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-5 border-t border-[var(--color-border)] bg-[var(--color-bg-secondary)] flex justify-between items-center">
                    <div>
                        {ticketType === 'Epic' && onPush && (
                            <button
                                onClick={onPush}
                                disabled={isPushing}
                                className="btn btn-primary bg-indigo-600 hover:bg-indigo-700 text-white flex items-center gap-2 border-transparent"
                            >
                                {isPushing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                                {isPushing ? 'Pushing to Jira...' : 'Push Epic to Jira'}
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} className="btn text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)] border-transparent">
                            Cancel
                        </button>
                        <button onClick={handleSave} className="btn btn-primary flex items-center gap-2">
                            <Save className="w-4 h-4" /> Save Changes
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect, useCallback } from 'react';
import { uploadPRD, pushSuggestionsToJira, createPRDSession, updatePRDSession, getPRDSession } from '../api/scrumApi';
import type { EpicSuggestion, PRDSuggestionsResponse, PushToJiraResponse, GeneratorOptions } from '../types/prd.types';

export type GeneratorState = 'idle' | 'uploading' | 'processing' | 'ready' | 'pushing' | 'done';

interface UsePRDGeneratorReturn {
    state: GeneratorState;
    epics: EpicSuggestion[];
    uploadProgress: number;
    error: string | null;
    sessionId: string | null;
    generatedBacklogId: string | null;
    generateSuggestions: (file: File | null, prompt: string, options: GeneratorOptions, projectKey?: string, businessDocIds?: string[]) => Promise<void>;
    pushToJira: (projectKey: string, selectedEpics: EpicSuggestion[]) => Promise<PushToJiraResponse>;
    resetgenerator: () => void;
    setEpics: React.Dispatch<React.SetStateAction<EpicSuggestion[]>>;
    loadSession: (id: string) => Promise<void>;
}

export { type GeneratorOptions };

export const usePRDGenerator = (
    initialSessionId?: string,
    boardId?: number | null,
): UsePRDGeneratorReturn => {
    const [state, setState] = useState<GeneratorState>('idle');
    const [epics, setEpics] = useState<EpicSuggestion[]>([]);
    const [uploadProgress, setUploadProgress] = useState(0);
    const [error, setError] = useState<string | null>(null);
    const [sessionId, setSessionId] = useState<string | null>(initialSessionId || null);
    const [generatedBacklogId, setGeneratedBacklogId] = useState<string | null>(null);

    // For debounced saving
    const [isDirty, setIsDirty] = useState(false);

    const [isPolling, setIsPolling] = useState(false);

    // Load session if ID provided
    const loadSession = useCallback(async (id: string) => {
        try {
            setState('processing');
            const session = await getPRDSession(id);
            setEpics(session.epics || []);
            setSessionId(session._id);
            setGeneratedBacklogId(session.generatedBacklogId || null);

            if (session.status === 'processing') {
                setState('processing');
                setIsPolling(true);
            } else if (session.status === 'failed') {
                setState('idle');
                setError(session.error || 'Generation failed.');
            } else {
                setState(session.epics?.length > 0 ? 'ready' : 'idle');
            }
        } catch (err: any) {
            console.error(err);
            setError("Failed to load session");
            setState('idle');
        }
    }, []);

    // Polling effect
    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPolling && sessionId) {
            interval = setInterval(async () => {
                try {
                    const session = await getPRDSession(sessionId);
                    if (session.status === 'ready') {
                        setEpics(session.epics || []);
                        setGeneratedBacklogId(session.generatedBacklogId || null);
                        setState('ready');
                        setIsPolling(false);
                    } else if (session.status === 'failed') {
                        setError(session.error || 'Generation failed.');
                        setState('idle');
                        setIsPolling(false);
                    }
                } catch (e) {
                    console.error("Polling error", e);
                }
            }, 3000);
        }
        return () => clearInterval(interval);
    }, [isPolling, sessionId]);

    // Auto-save effect (Debounced)
    useEffect(() => {
        if (!sessionId || !isDirty || state === 'processing' || isPolling) return;

        const timeoutId = setTimeout(async () => {
            try {
                await updatePRDSession(sessionId, { epics });
                setIsDirty(false);
            } catch (err) {
                console.error("Failed to auto-save session", err);
            }
        }, 2000); // 2 second debounce

        return () => clearTimeout(timeoutId);
    }, [epics, sessionId, isDirty, state, isPolling]);

    // Mark dirty on epics change
    useEffect(() => {
        if (sessionId && epics.length > 0 && !isPolling) {
            setIsDirty(true);
        }
    }, [epics, sessionId, isPolling]);

    const generateSuggestions = async (file: File | null, prompt: string, options: GeneratorOptions, projectKey?: string, businessDocIds?: string[]) => {
        try {
            setError(null);

            if (!file && !prompt.trim()) {
                setError("Please upload a PDF or enter instructions.");
                return;
            }

            setState('uploading');
            let currentSessionId = sessionId;

            // Create or Update Session first
            if (currentSessionId) {
                await updatePRDSession(currentSessionId, { prompt, options });
            } else {
                const newSession = await createPRDSession({
                    epics: [],
                    prompt,
                    options,
                    title: file ? `PRD: ${file.name}` : `Prompt: ${prompt.substring(0, 20)}...`
                });
                currentSessionId = newSession._id;
                setSessionId(newSession._id);
            }

            // Simulate upload progress
            const interval = setInterval(() => {
                setUploadProgress(prev => {
                    if (prev >= 90) {
                        clearInterval(interval);
                        return 90;
                    }
                    return prev + 10;
                });
            }, 200);

            // Trigger generation
            const response = await uploadPRD(file, boardId, projectKey, businessDocIds, currentSessionId, prompt);

            clearInterval(interval);
            setUploadProgress(100);

            if (response.status === 'processing') {
                setState('processing');
                setIsPolling(true);
            } else {
                // Synchronous fallback just in case
                if (response.success && (response.data?.epics || response.data)) {
                    setEpics(response.data.epics || response.data);
                    setState('ready');
                } else {
                    throw new Error(response.message || 'Failed to start generation');
                }
            }

        } catch (err: any) {
            console.error(err);
            setError(err.message || "An unexpected error occurred.");
            setState('idle');
            setIsPolling(false);
        }
    };

    const pushToJira = async (projectKey: string, selectedEpics: EpicSuggestion[]): Promise<PushToJiraResponse> => {
        setState('pushing');
        try {
            const response = await pushSuggestionsToJira({
                projectKey,
                suggestions: {
                    data: {
                        epics: selectedEpics
                    }
                }
            });

            setState('done');
            return response;
        } catch (err: any) {
            console.error(err);
            setError(err.message || "Failed to push to Jira.");
            setState('ready');
            throw err;
        }
    };

    const resetgenerator = () => {
        setState('idle');
        setEpics([]);
        setError(null);
        setUploadProgress(0);
        setSessionId(null);
        setGeneratedBacklogId(null);
    };

    return {
        state,
        epics,
        uploadProgress,
        error,
        sessionId,
        generatedBacklogId,
        generateSuggestions,
        pushToJira,
        resetgenerator,
        setEpics,
        loadSession
    };
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getGeneratedBacklog, updateStory, approveAndPushEpic, type GeneratedBacklog } from '../api/generatedBacklogApi';
import { useWorkspaceStore } from '../store/useWorkspaceStore';
import { Check, X, Edit2, Play, AlertCircle, Loader2 } from 'lucide-react';

export const BacklogReviewPage: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const workspace = useWorkspaceStore((state) => state.workspace);
    const [backlog, setBacklog] = useState<GeneratedBacklog | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Polling setup for background pushes
    const [isPolling, setIsPolling] = useState(false);

    useEffect(() => {
        if (!id) return;
        fetchBacklog();
    }, [id]);

    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPolling && id) {
            interval = setInterval(() => {
                fetchBacklog(true);
            }, 3000);
        }
        return () => clearInterval(interval);
    }, [isPolling, id]);

    const fetchBacklog = async (silent = false) => {
        if (!silent) setLoading(true);
        try {
            const data = await getGeneratedBacklog(id!);
            setBacklog(data);
            setError(null);

            // Check if we need to poll
            const hasPushing = data.epic_statuses.some((e: any) => e.status === 'pushing');
            setIsPolling(hasPushing);

        } catch (err: any) {
            if (!silent) setError(err.message || 'Failed to load backlog');
        } finally {
            if (!silent) setLoading(false);
        }
    };

    const handlePushEpic = async (epicId: string) => {
        if (!id) return;
        try {
            await approveAndPushEpic(id, epicId);
            fetchBacklog(); // Fetch immediately to see 'pushing' status
        } catch (err: any) {
            alert(`Failed to push epic: ${err.message}`);
        }
    };

    const handlePushAll = async () => {
        if (!id || !backlog) return;

        // Find epics that are pending or failed (if tracking exists)
        if (backlog.epic_statuses && backlog.epic_statuses.length > 0) {
            const epicsToPush = backlog.epic_statuses.filter((e: any) => e.status === 'pending_review' || e.status === 'failed');
            if (epicsToPush.length === 0) return;
        }

        try {
            await approveAndPushEpic(id, null); // null epicId pushes all
            fetchBacklog(); // Fetch immediately to see 'pushing' status
        } catch (err: any) {
            alert(`Failed to push all epics: ${err.message}`);
        }
    };

    if (loading) {
        return <div className="p-8 flex items-center justify-center h-full"><Loader2 className="w-8 h-8 animate-spin text-[var(--color-accent)]" /></div>;
    }

    if (error || !backlog) {
        return <div className="p-8 text-red-500">{error || 'Backlog not found'}</div>;
    }

    const { orchestrator_contract, stories, epic_statuses, validation_report } = backlog;
    const hasPendingOrFailedEpics = !epic_statuses || epic_statuses.length === 0 || epic_statuses.some((e: any) => e.status === 'pending_review' || e.status === 'failed');
    const isPushing = epic_statuses?.some((e: any) => e.status === 'pushing');

    return (
        <div className="flex flex-col h-full bg-[var(--color-surface)] overflow-y-auto custom-scrollbar">
            {/* Header */}
            <div className="sticky top-0 z-10 bg-[var(--color-bg-primary)] border-b border-[var(--color-border)] p-6 shadow-sm">
                <div className="flex justify-between items-center max-w-5xl mx-auto">
                    <div>
                        <h1 className="text-2xl font-bold text-[var(--color-text-primary)]">Review Generated Backlog</h1>
                        <p className="text-sm text-[var(--color-text-secondary)] mt-1">
                            {validation_report?.passed} stories passed, {validation_report?.failed_and_flagged} flagged.
                        </p>
                    </div>
                    <div className="flex gap-4 items-center">
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${backlog.status === 'fully_pushed' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                            {backlog.status.replace('_', ' ').toUpperCase()}
                        </span>

                        {(hasPendingOrFailedEpics || backlog.status === 'pending_review') && (
                            <button
                                onClick={handlePushAll}
                                disabled={isPushing}
                                className="btn btn-primary flex items-center gap-2"
                            >
                                {isPushing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                                {isPushing ? 'Pushing...' : 'Push All to Jira'}
                            </button>
                        )}

                        <button
                            onClick={() => navigate('/prd')}
                            className="btn btn-secondary"
                        >
                            Back to Generator
                        </button>
                    </div>
                </div>
            </div>

            {/* Content */}
            <div className="p-6 max-w-5xl mx-auto w-full space-y-8">
                {orchestrator_contract?.epics?.map((epic: any) => {
                    const epicStories = stories.filter(s => s.epic_id === epic.id);
                    const epicStatus = epic_statuses?.find((e: any) => e.epic_id === epic.id);
                    const isPending = !epicStatus || epicStatus.status === 'pending_review';

                    return (
                        <div key={epic.id} className="bg-[var(--color-bg-primary)] rounded-xl border border-[var(--color-border)] overflow-hidden shadow-sm">
                            {/* Epic Header */}
                            <div className="p-5 border-b border-[var(--color-border)] bg-[var(--color-bg-secondary)] flex justify-between items-start">
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="px-2 py-1 text-xs font-bold bg-purple-100 text-purple-700 rounded uppercase tracking-wider">Epic</span>
                                        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">{epic.title}</h2>
                                    </div>
                                    <p className="text-sm text-[var(--color-text-secondary)] max-w-3xl">{epic.description}</p>
                                </div>
                                <div className="flex flex-col items-end gap-2">
                                    {isPending && (
                                        <button 
                                            onClick={() => handlePushEpic(epic.id)}
                                            className="btn btn-primary flex items-center gap-2"
                                        >
                                            <Play className="w-4 h-4" /> Push Epic
                                        </button>
                                    )}
                                    {epicStatus?.status === 'pushing' && (
                                        <div className="flex items-center gap-2 text-blue-600 font-medium">
                                            <Loader2 className="w-4 h-4 animate-spin" /> Pushing...
                                        </div>
                                    )}
                                    {epicStatus?.status === 'pushed' && (
                                        <div className="flex items-center gap-2 text-green-600 font-medium bg-green-50 px-3 py-1 rounded-full">
                                            <Check className="w-4 h-4" /> Pushed
                                        </div>
                                    )}
                                    {epicStatus?.status === 'failed' && (
                                        <div className="flex flex-col items-end gap-1">
                                            <div className="flex items-center gap-2 text-red-600 font-medium bg-red-50 px-3 py-1 rounded-full">
                                                <AlertCircle className="w-4 h-4" /> Push Failed
                                            </div>
                                            <button 
                                                onClick={() => handlePushEpic(epic.id)}
                                                className="text-xs text-blue-600 hover:underline"
                                            >
                                                Retry
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Epic Stories */}
                            <div className="divide-y divide-[var(--color-border-light)]">
                                {epicStories.map((story) => (
                                    <StoryReviewItem 
                                        key={story.story_id} 
                                        story={story} 
                                        backlogId={id!} 
                                        isEditable={epicStatus?.status === 'pending_review' || epicStatus?.status === 'failed'} 
                                    />
                                ))}
                                {epicStories.length === 0 && (
                                    <div className="p-6 text-center text-[var(--color-text-tertiary)] text-sm">
                                        No stories drafted for this epic.
                                    </div>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// Sub-component for individual story review
const StoryReviewItem = ({ story, backlogId, isEditable }: { story: any, backlogId: string, isEditable: boolean }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedStory, setEditedStory] = useState(story);
    const [saving, setSaving] = useState(false);

    const handleSave = async () => {
        setSaving(true);
        try {
            await updateStory(backlogId, story.story_id, editedStory);
            setIsEditing(false);
        } catch (err) {
            alert('Failed to save changes');
        } finally {
            setSaving(false);
        }
    };

    if (isEditing && isEditable) {
        return (
            <div className="p-5 bg-white space-y-4 relative">
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">User Story</label>
                    <input 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm focus:ring-2 focus:ring-[var(--color-accent)]"
                        value={editedStory.user_story}
                        onChange={e => setEditedStory({...editedStory, user_story: e.target.value})}
                    />
                </div>
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">Description</label>
                    <textarea 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm h-24 focus:ring-2 focus:ring-[var(--color-accent)] custom-scrollbar"
                        value={editedStory.description}
                        onChange={e => setEditedStory({...editedStory, description: e.target.value})}
                    />
                </div>
                <div>
                    <label className="block text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider mb-1">Acceptance Criteria</label>
                    <textarea 
                        className="w-full border border-[var(--color-border)] rounded-md p-2 text-sm h-32 focus:ring-2 focus:ring-[var(--color-accent)] custom-scrollbar"
                        value={(editedStory.acceptance_criteria || []).join('\n')}
                        onChange={e => setEditedStory({...editedStory, acceptance_criteria: e.target.value.split('\n')})}
                        placeholder="One criterion per line"
                    />
                </div>
                <div className="flex justify-end gap-3 pt-2">
                    <button className="btn text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-secondary)]" onClick={() => { setIsEditing(false); setEditedStory(story); }}>Cancel</button>
                    <button className="btn btn-primary" onClick={handleSave} disabled={saving}>{saving ? 'Saving...' : 'Save Changes'}</button>
                </div>
            </div>
        );
    }

    return (
        <div className="p-5 hover:bg-[var(--color-bg-secondary)] transition-colors group relative">
            <div className="flex justify-between items-start">
                <div className="flex items-start gap-3">
                    <span className="px-2 py-0.5 mt-0.5 text-xs font-bold bg-blue-100 text-blue-700 rounded uppercase tracking-wider">Story</span>
                    <div>
                        <h4 className="text-sm font-semibold text-[var(--color-text-primary)] leading-snug">{story.user_story}</h4>
                        <div className="flex items-center gap-3 mt-2 text-xs text-[var(--color-text-tertiary)] font-medium">
                            <span className="bg-[var(--color-bg-tertiary)] px-2 py-0.5 rounded text-[var(--color-text-secondary)]">{story.story_points} pts</span>
                            <span>{story.priority}</span>
                            <span>Sprint {story.sprint}</span>
                            {story.validation_status === 'failed' && (
                                <span className="flex items-center gap-1 text-red-600 bg-red-50 px-2 py-0.5 rounded">
                                    <AlertCircle className="w-3 h-3" /> Flagged
                                </span>
                            )}
                        </div>
                    </div>
                </div>
                {isEditable && (
                    <button 
                        onClick={() => setIsEditing(true)}
                        className="p-1.5 text-[var(--color-text-tertiary)] hover:text-[var(--color-accent)] hover:bg-[var(--color-accent-lighter)] rounded-md opacity-0 group-hover:opacity-100 transition-all"
                    >
                        <Edit2 className="w-4 h-4" />
                    </button>
                )}
            </div>

            {(story.description || (story.acceptance_criteria && story.acceptance_criteria.length > 0)) && (
                <div className="mt-4 ml-12 text-sm text-[var(--color-text-secondary)] bg-white border border-[var(--color-border-light)] p-3 rounded-lg shadow-sm">
                    {story.description && (
                        <div className="mb-3">
                            <strong className="text-xs uppercase tracking-wider text-[var(--color-text-tertiary)] mb-1 block">Description</strong>
                            <p className="whitespace-pre-wrap">{story.description}</p>
                        </div>
                    )}
                    {story.acceptance_criteria && story.acceptance_criteria.length > 0 && (
                        <div>
                            <strong className="text-xs uppercase tracking-wider text-[var(--color-text-tertiary)] mb-1 block">Acceptance Criteria</strong>
                            <ul className="list-disc pl-5 space-y-1">
                                {story.acceptance_criteria.map((ac: string, i: number) => (
                                    <li key={i}>{ac}</li>
                                ))}
                            </ul>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

