import React, { useEffect, useState, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useAuthStore } from "../store/useAuthStore";
import { useChatStore } from "../hooks/useChatSessions";
import { useChat } from "../hooks/useChat";
import { getPushHistory } from "../api/backlogApi";
import type { PushedBacklogRecord } from "../types/chat.types";
import ChatLayout from "../components/chat/ChatLayout";
import ChatSidebar from "../components/chat/ChatSidebar";
import { ChatHeader } from "../components/chat/ChatHeader";
import ChatMessages from "../components/chat/ChatMessages";
import ChatInputBar from "../components/chat/ChatInputBar";
import PushHistoryPanel from "../components/chat/PushHistoryPanel";
import { useWorkspaceStore } from "../store/useWorkspaceStore";

const ChatPage: React.FC = () => {
  const { sessionId: urlSessionId } = useParams();
  const navigate = useNavigate();
  const { token } = useAuthStore();
  const workspace = useWorkspaceStore((state) => state.workspace);
  const {
    sessions,
    activeSessionId,
    sessionsLoaded,
    loadSessions,
    createSession,
    deleteSession,
    renameSession,
    updateSessionTitleLocal,
    setActiveSession,
  } = useChatStore();

  // Refresh trigger for push history panel
  const [historyRefreshTrigger, setHistoryRefreshTrigger] = useState(0);
  const [pushedSessionItems, setPushedSessionItems] = useState<PushedBacklogRecord[]>([]);

  // Hook up chat logic
  const {
    messages,
    loading: isChatLoading,
    error: chatError,
    sendMessage,
    resetError,
  } = useChat(activeSessionId, (newTitle) => {
    if (activeSessionId) {
      updateSessionTitleLocal(activeSessionId, newTitle);
    }
  });

  const loadSessionHistory = useCallback(async () => {
    if (activeSessionId) {
      try {
        const history = await getPushHistory(activeSessionId);
        setPushedSessionItems(history);
      } catch (err) {
        console.error("Failed to fetch session history for chat parsing:", err);
      }
    } else {
      setPushedSessionItems([]);
    }
  }, [activeSessionId, historyRefreshTrigger]);

  // 1. Initial Load
  useEffect(() => {
    if (token) {
      loadSessions(token, workspace?.boardId);
    }
  }, [token, workspace?.boardId, loadSessions]);

  useEffect(() => {
    loadSessionHistory();
  }, [loadSessionHistory]);

  // 2. Sync URL -> Store & Auto-open
  useEffect(() => {
    if (!sessionsLoaded) return; // Wait until sessions are loaded before redirecting

    if (urlSessionId && urlSessionId !== activeSessionId) {
      setActiveSession(urlSessionId);
    } else if (!urlSessionId) {
      if (sessions.length > 0) {
        const mostRecent = sessions[0];
        navigate(`/chat/${mostRecent._id}`, { replace: true });
      } else {
        setActiveSession(null);
      }
    }
  }, [urlSessionId, setActiveSession, activeSessionId, sessions, sessionsLoaded, navigate]);

  // 3. Handlers
  const handleSelectSession = (id: string) => {
    setActiveSession(id);
    navigate(`/chat/${id}`);
  };

  const handleCreateSession = async () => {
    if (token) {
      const newId = await createSession(token, workspace?.boardId);
      if (newId) {
        navigate(`/chat/${newId}`);
      }
    }
  };

  const handleDeleteSession = async (sessionId: string) => {
    if (token) await deleteSession(sessionId, token);
    if (sessionId === activeSessionId) {
      navigate("/chat");
    }
  };

  const handleRenameSession = async (sessionId: string, newTitle: string) => {
    if (token) await renameSession(sessionId, newTitle, token);
  };

  const handleSendMessage = async (text: string) => {
    await sendMessage(text, {
      boardId: workspace?.boardId ?? null,
      sprintId: workspace?.sprintId ?? null,
    });
  };

  const handleBacklogPushed = () => {
    // Trigger a refresh of the push history panel
    setHistoryRefreshTrigger((prev) => prev + 1);
  };

  return (
    <>
      <ChatLayout
        sidebar={
          <ChatSidebar
            sessions={sessions}
            activeSessionId={activeSessionId}
            onSelectSession={handleSelectSession}
            onCreateSession={handleCreateSession}
            onDeleteSession={handleDeleteSession}
            onRenameSession={handleRenameSession}
          />
        }
        chatArea={
          <>
            <ChatHeader loading={isChatLoading} />

            {/* Error Toast */}
            {chatError && (
              <div className="absolute top-[var(--space-4)] left-1/2 transform -translate-x-1/2 z-[var(--z-toast)]">
                <div className="toast toast-error shadow-lg flex items-center">
                  <svg className="w-5 h-5 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <span>{chatError}</span>
                  <button onClick={resetError} className="toast-dismiss ml-2 text-current">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              </div>
            )}

            <ChatMessages
              messages={messages}
              loading={isChatLoading}
              sessionId={activeSessionId}
              pushedSessionItems={pushedSessionItems}
              onBacklogPushed={handleBacklogPushed}
            />
            <ChatInputBar onSend={handleSendMessage} disabled={isChatLoading} />
          </>
        }
      />
      <PushHistoryPanel
        sessionId={activeSessionId}
        refreshTrigger={historyRefreshTrigger}
      />
    </>
  );
};

export default ChatPage;

import React, { useState, useEffect, useRef } from "react";
import api from "../api/axios";
import { useWorkspaceStore } from "../store/useWorkspaceStore";

interface BusinessDocument {
  _id: string;
  filename: string;
  syncStatus: "PENDING" | "SYNCED" | "FAILED";
  createdAt: string;
}

const DocumentsPage: React.FC = () => {
  const [documents, setDocuments] = useState<BusinessDocument[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const workspace = useWorkspaceStore((state) => state.workspace);

  useEffect(() => {
    fetchDocuments();
  }, [workspace?.boardId]);

  const fetchDocuments = async () => {
    try {
      const url = workspace?.boardId 
        ? `/api/v1/documents?boardId=${workspace.boardId}`
        : "/api/v1/documents";
      const response = await api.get(url);
      setDocuments(response.data);
    } catch (err: any) {
      setError(err.response?.data?.error || "Failed to fetch documents");
    }
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);
    if (workspace?.boardId) {
      formData.append("boardId", workspace.boardId.toString());
    }

    setIsUploading(true);
    setError(null);
    try {
      await api.post("/api/v1/documents/upload", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      fetchDocuments();
    } catch (err: any) {
      setError(err.response?.data?.error || "Failed to upload document");
    } finally {
      setIsUploading(false);
      // Reset input
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm("Are you sure you want to delete this document?")) return;

    try {
      await api.delete(`/api/v1/documents/${id}`);
      setDocuments(documents.filter((doc) => doc._id !== id));
    } catch (err: any) {
      setError(err.response?.data?.error || "Failed to delete document");
    }
  };

  return (
    <div className="page-layout">
      <div className="page-header-row">
        <div>
          <h1 className="page-title">Business Documents</h1>
          <p className="page-subtitle">
            Upload requirements, specs, and business context documents for the AI to reference.
          </p>
        </div>
        <button
          onClick={handleUploadClick}
          disabled={isUploading}
          className="btn btn-primary"
        >
          {isUploading ? "Uploading..." : "Upload Document"}
        </button>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          accept=".pdf,.txt,.md"
          className="hidden"
        />
      </div>

      {error && (
        <div className="bg-[var(--color-error-light)] text-[var(--color-error)] p-3 rounded mb-4 text-sm border border-[var(--color-error)]">
          {error}
        </div>
      )}

      <div className="doc-list-container">
        {documents.length === 0 ? (
          <div className="doc-empty-state">
            <svg className="doc-empty-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path>
            </svg>
            <p className="doc-empty-title">No documents yet</p>
            <p className="doc-empty-desc">Upload PDF or Text files to provide business context.</p>
          </div>
        ) : (
          <ul className="doc-list">
            {documents.map((doc) => (
              <li key={doc._id} className="doc-list-item">
                <div className="doc-info-wrapper">
                  <div className="doc-icon-box">
                    <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path>
                    </svg>
                  </div>
                  <div>
                    <p className="doc-filename">{doc.filename}</p>
                    <p className="doc-date">
                      Uploaded on {new Date(doc.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                </div>
                <div className="doc-actions-wrapper">
                  <span
                    className={`badge ${
                      doc.syncStatus === "SYNCED"
                        ? "badge-success"
                        : doc.syncStatus === "FAILED"
                        ? "badge-error"
                        : "badge-warning"
                    }`}
                  >
                    {doc.syncStatus}
                  </span>
                  <button
                    onClick={() => handleDelete(doc._id)}
                    className="btn-icon-sm text-[var(--color-text-tertiary)] hover:text-[var(--color-error)]"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
                    </svg>
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default DocumentsPage;

import { create } from 'zustand';

const isTokenValid = (token: string | null) => {
    if (!token) return false;
    try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        // Check if exp exists and if it is in the past
        if (payload.exp && payload.exp * 1000 < Date.now()) {
            return false;
        }
        return true;
    } catch (e) {
        return false;
    }
};

const getInitialToken = () => {
    const token = localStorage.getItem('token');
    if (isTokenValid(token)) return token;
    localStorage.removeItem('token');
    return null;
};

interface AuthStore {
    token: string | null;
    setToken: (token: string | null) => void;
    logout: () => void;
}

export const useAuthStore = create<AuthStore>((set) => ({
    token: getInitialToken(),
    setToken: (token) => {
        if (token && isTokenValid(token)) {
            localStorage.setItem('token', token);
            set({ token });
        } else {
            localStorage.removeItem('token');
            set({ token: null });
        }
    },
    logout: () => {
        localStorage.removeItem('token');
        set({ token: null });
    }
}));
